def find_ways(n, k):
    # Initialize the dp array
    dp = [[0 for _ in range(k + 1)] for _ in range(n + 1)]

    # Fill the dp array
    for i in range(n + 1):
        dp[i][0] = 1
    for j in range(1, k + 1):
        dp[0][j] = 0

    # Fill the dp array
    for i in range(1, n + 1):
        for j in range(1, k + 1):
            dp[i][j] = dp[i - 1][j] + dp[i - 1][j - 1] + dp[i - 1][j - 2]
            if j >= i:
                dp[i][j] -= dp[i - 1][j - i]

    # Return the number of ways
    return dp[n][k]

