def get_maxgold(matrix, m, n):
    # Initialize the matrix with zeros
    matrix = [[0 for _ in range(n)] for _ in range(m)]

    # Initialize the maximum gold to 0
    max_gold = 0

    # Iterate through the matrix
    for i in range(m):
        for j in range(n):
            # If the cell is empty
            if matrix[i][j] == 0:
                # Iterate through the adjacent cells
                for k in range(i-1, i+2):
                    for l in range(j-1, j+2):
                        # If the adjacent cell is not out of bounds
                        if 0 <= k < m and 0 <= l < n:
                            # If the adjacent cell is empty
                            if matrix[k][l] == 0:
                                # Update the maximum gold
                                max_gold = max(max_gold, matrix[i][j] + matrix[k][l])

    # Return the maximum gold
    return max_gold

