def sum_gp(a, r, n):
    """
    This function takes in three arguments: a, r, and n.
    It returns the sum of the geometric progression series.
    """
    if r == 1:
        return a * n
    else:
        return a * (1 - r**n) / (1 - r)

def binary_search(arr, x):
    low = 0
    high = len(arr) - 1
    while low <= high:
        mid = (low + high) // 2
        if arr[mid] == x:
            return mid
        elif arr[mid] > x:
            high = mid - 1
        else:
            low = mid + 1
    return -1

def calculate_polygons(x, y, width, height, num):
    polygons = []
    for i in range(num):
        polygons.append([])
        for j in range(num):
            polygons[i].append([])
            for k in range(num):
                polygons[i][j].append([])
                for l in range(num):
                    polygons[i][j][k].append([])
                    polygons[i][j][k][l] = [x + (width * i), y + (height * j), x + (width * k), y + (height * l)]
    return polygons

